content:
:root {
  color-scheme: light dark;
  --bg: #f4f6f8;
  --bg-elevated: #ffffff;
  --fg: #0f172a;
  --fg-muted: #64748b;
  --panel: #f8fafc;
  --border: #e2e8f0;
  --accent: #2563eb;
  --accent-hover: #1d4ed8;
  --accent-soft: #dbeafe;
  --danger: #b91c1c;
  --radius: 10px;
  --shadow: 0 1px 2px rgb(15 23 42 / 6%), 0 8px 24px rgb(15 23 42 / 6%);
  --font: "Segoe UI", system-ui, -apple-system, sans-serif;
  --mono: ui-monospace, "Cascadia Code", "SF Mono", Menlo, monospace;
}

.theme-dark {
  --bg: #0b1220;
  --bg-elevated: #111827;
  --fg: #e5e7eb;
  --fg-muted: #94a3b8;
  --panel: #0f172a;
  --border: #1e293b;
  --accent: #3b82f6;
  --accent-hover: #60a5fa;
  --accent-soft: #1e3a5f;
  --shadow: 0 1px 2px rgb(0 0 0 / 40%), 0 12px 32px rgb(0 0 0 / 35%);
}

@media (prefers-color-scheme: dark) {
  .theme-auto {
    --bg: #0b1220;
    --bg-elevated: #111827;
    --fg: #e5e7eb;
    --fg-muted: #94a3b8;
    --panel: #0f172a;
    --border: #1e293b;
    --accent: #3b82f6;
    --accent-hover: #60a5fa;
    --accent-soft: #1e3a5f;
    --shadow: 0 1px 2px rgb(0 0 0 / 40%), 0 12px 32px rgb(0 0 0 / 35%);
  }
}

* {
  box-sizing: border-box;
}

html,
body,
#root {
  height: 100%;
}

body {
  margin: 0;
  font-family: var(--font);
  background: var(--bg);
  color: var(--fg);
  line-height: 1.45;
}

button,
input,
select {
  font: inherit;
}

.app {
  display: flex;
  flex-direction: column;
  min-height: 100%;
  height: 100%;
}

/* Top bar */
.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 0.65rem 1rem;
  background: var(--bg-elevated);
  border-bottom: 1px solid var(--border);
  box-shadow: var(--shadow);
  z-index: 2;
}

.brand {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.brand-mark {
  display: grid;
  place-items: center;
  width: 2rem;
  height: 2rem;
  border-radius: 8px;
  background: linear-gradient(145deg, var(--accent), #7c3aed);
  color: white;
  font-size: 0.75rem;
  font-weight: 800;
  letter-spacing: 0.02em;
}

.brand strong {
  display: block;
  font-size: 0.95rem;
}

.brand-sub {
  display: block;
  color: var(--fg-muted);
  font-size: 0.75rem;
}

.topbar-actions {
  display: flex;
  gap: 0.5rem;
}

/* Workspace grid */
.workspace {
  display: grid;
  grid-template-columns: minmax(240px, 280px) minmax(0, 1fr) minmax(220px, 260px);
  flex: 1;
  min-height: 0;
}

.panel {
  background: var(--panel);
  border-right: 1px solid var(--border);
  padding: 0.85rem;
  overflow: auto;
  min-height: 0;
}

.panel.right {
  border-right: 0;
  border-left: 1px solid var(--border);
}

.panel-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  margin-bottom: 0.75rem;
}

.panel h2 {
  margin: 0;
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--fg-muted);
  font-weight: 700;
}

.workspace-badge {
  max-width: 9rem;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 0.7rem;
  padding: 0.15rem 0.45rem;
  border-radius: 999px;
  background: var(--accent-soft);
  color: var(--accent);
}

.center {
  display: grid;
  min-width: 0;
  min-height: 0;
  background: var(--bg);
}

.center.mode-split {
  grid-template-rows: 1fr 1fr;
}

.center.mode-source,
.center.mode-preview {
  grid-template-rows: 1fr;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.4rem;
  border: 1px solid transparent;
  border-radius: 8px;
  padding: 0.55rem 0.75rem;
  cursor: pointer;
  font-weight: 600;
  font-size: 0.875rem;
  transition: background 0.15s ease, border-color 0.15s ease, color 0.15s ease;
}

.btn:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.btn-primary {
  background: var(--accent);
  color: #fff;
}

.btn-primary:hover:not(:disabled) {
  background: var(--accent-hover);
}

.btn-secondary {
  background: var(--bg-elevated);
  color: var(--fg);
  border-color: var(--border);
}

.btn-secondary:hover:not(:disabled) {
  border-color: var(--accent);
  color: var(--accent);
}

.btn-sm {
  padding: 0.4rem 0.7rem;
  font-size: 0.8rem;
}

.btn-icon {
  font-size: 1rem;
  line-height: 1;
}

.open-actions {
  display: grid;
  gap: 0.5rem;
  margin-bottom: 0.85rem;
}

.open-actions .btn {
  width: 100%;
}

/* Fields */
.field {
  display: grid;
  gap: 0.3rem;
  margin-bottom: 0.75rem;
  font-size: 0.8rem;
  color: var(--fg-muted);
}

.field input,
.field select,
.card select {
  width: 100%;
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 0.5rem 0.65rem;
  background: var(--bg-elevated);
  color: var(--fg);
}

.field input:focus,
.field select:focus,
.card select:focus {
  outline: 2px solid color-mix(in srgb, var(--accent) 45%, transparent);
  border-color: var(--accent);
}

/* Banners / empty */
.banner {
  margin: 0 0 0.75rem;
  padding: 0.55rem 0.65rem;
  border-radius: 8px;
  font-size: 0.78rem;
  line-height: 1.4;
}

.banner code {
  font-family: var(--mono);
  font-size: 0.72rem;
}

.banner-info {
  background: var(--accent-soft);
  color: var(--fg);
  border: 1px solid color-mix(in srgb, var(--accent) 25%, var(--border));
}

.banner-muted {
  background: var(--bg-elevated);
  color: var(--fg-muted);
  border: 1px solid var(--border);
}

.empty-state {
  padding: 1.25rem 0.5rem;
  text-align: center;
  color: var(--fg-muted);
  font-size: 0.85rem;
}

.empty-state .muted {
  opacity: 0.85;
  font-size: 0.8rem;
}

/* Breadcrumb */
.breadcrumb {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.15rem;
  margin-bottom: 0.65rem;
  padding: 0.35rem 0.4rem;
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: 8px;
  font-size: 0.78rem;
}

.crumb {
  border: none;
  background: transparent;
  color: var(--accent);
  cursor: pointer;
  padding: 0.15rem 0.3rem;
  border-radius: 4px;
  font-weight: 600;
}

.crumb:hover:not(:disabled) {
  background: var(--accent-soft);
}

.crumb:disabled,
.crumb.is-current {
  color: var(--fg);
  cursor: default;
}

.crumb-sep {
  color: var(--fg-muted);
  user-select: none;
}

.crumb-up {
  margin-left: auto;
}

.file-meta {
  margin-left: auto;
  font-size: 0.7rem;
  color: var(--fg-muted);
}

.file-item.is-dir .file-name {
  font-weight: 600;
}

/* File list */
.file-list-wrap {
  min-height: 8rem;
}

.file-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 0.25rem;
}

.file-item {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 0.45rem;
  text-align: left;
  border: 1px solid transparent;
  background: transparent;
  color: var(--fg);
  border-radius: 8px;
  padding: 0.45rem 0.5rem;
  cursor: pointer;
}

.file-item:hover {
  background: var(--bg-elevated);
  border-color: var(--border);
}

.file-item.is-active {
  background: var(--accent-soft);
  border-color: color-mix(in srgb, var(--accent) 35%, var(--border));
  color: var(--accent);
  font-weight: 600;
}

.file-name {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* Editor / preview */
.editor,
.preview {
  min-height: 0;
  display: flex;
  flex-direction: column;
  border-bottom: 1px solid var(--border);
  background: var(--bg-elevated);
}

.editor header,
.code-block header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 0.5rem;
  padding: 0.4rem 0.75rem;
  border-bottom: 1px solid var(--border);
  background: var(--panel);
  font-size: 0.8rem;
  color: var(--fg-muted);
}

.editor-host {
  flex: 1;
  min-height: 0;
  overflow: hidden;
}

.editor .cm-editor {
  height: 100%;
  font-size: 0.92rem;
}

.editor .cm-scroller {
  font-family: var(--mono);
  height: 100%;
}

.preview-body {
  padding: 1.25rem 1.5rem;
  overflow: auto;
  max-width: 52rem;
}

.preview-body h1,
.preview-body h2,
.preview-body h3 {
  line-height: 1.25;
}

.preview-body pre {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 0.75rem 1rem;
  overflow: auto;
}

.preview-body code {
  font-family: var(--mono);
  font-size: 0.88em;
}

/* Right cards */
.card,
.outline,
.panel.right > section {
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 0.75rem;
  margin-bottom: 0.75rem;
}

.outline ul,
.diag-list {
  margin: 0.4rem 0 0;
  padding-left: 1.1rem;
  font-size: 0.85rem;
}

.diag-list {
  list-style: disc;
  color: var(--fg-muted);
}

.panel.right label {
  display: grid;
  gap: 0.25rem;
  margin-top: 0.5rem;
  font-size: 0.8rem;
  color: var(--fg-muted);
}

@media (max-width: 960px) {
  .workspace {
    grid-template-columns: 1fr;
    grid-template-rows: auto 1fr auto;
  }
  .panel.right {
    border-left: 0;
    border-top: 1px solid var(--border);
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    transition: none !important;
    animation: none !important;
  }
}
